    let mut leading: Vec<char> = Vec::new();

    let mut add_terms = |terms: &str, sign: i128| {
        for word in terms.split(" + ").map(str::trim) {
            if word.is_empty() {
                continue;
            }
            if word.len() > 1 {
                leading.push(word.chars().next().unwrap());
            }
            let mut place: i128 = 1;
            for ch in word.chars().rev() {
                *coeffs.entry(ch).or_insert(0) += sign * place;
                place *= 10;
            }
